const serverRowDm: NewServerRow = {
  ...serverRow,
  id: '501',
  digestMode: 'dm',
  digestCron: '0 10 * * *',
  digestTimezone: 'UTC',
  enabledGames: '["mtg"]',
  adminChannelId: null,
  digestDmUserId: 'dm-user-1',
  lastDigestAt: 0,
  removedAt: null,
  createdAt: 1,
  updatedAt: 1,
};

function fakeClientWithDmSend(fetchUser: (userId: string) => Promise<unknown>): Client {
  return {
    users: {
      fetch: vi.fn().mockImplementation(async (userId: string) => {
        if (userId === 'dm-user-1') {
          return {
            send: vi.fn().mockImplementation((msg: { content: string; allowedMentions?: unknown }) => {
              return Promise.resolve();
            }),
          } as unknown as import('discord.js').User;
        }
        return null as unknown as import('discord.js').User;
      }),
    },
  } as unknown as Client;
}

describe('runDigest DM delivery', () => {
  it('passes allowedMentions with parse: [] to DM send', async () => {
    getDb().insert(servers).values(serverRowDm).run();
    addListing();

    const sent: { content: string; allowedMentions?: unknown }[] = [];
    const fetchUser = vi.fn().mockImplementation(async (userId: string) => {
      if (userId === 'dm-user-1') {
        return {
          send: vi.fn().mockImplementation((msg: { content: string; allowedMentions?: unknown }) => {
            sent.push(msg);
            return Promise.resolve();
          }),
        } as unknown as import('discord.js').User;
      }
      return null as unknown as import('discord.js').User;
    });
    const client = fakeClientWithDmSend(fetchUser);

    const result = await runDigest(client, getServerConfig('501')!, 'scheduled');

    expect(result.sent).toBe(true);
    expect(result.dmOk).toBe(true);
    expect(result.channelOk).toBe(false);
    expect(sent).toHaveLength(1);
    expect(sent[0]).toHaveProperty('content');
    expect(sent[0]).toHaveProperty('allowedMentions');
    expect(sent[0].allowedMentions).toEqual({ parse: [] });
  });
});

