function fakeClientWithChannelSend(
  send: (message?: { content?: string; allowedMentions?: unknown }) => Promise<unknown>,
): Client {
  return {
    channels: {
      fetch: vi.fn().mockResolvedValue({
        isTextBased: () => true,
        isSendable: () => true,
        send,
      }),
    },
  } as unknown as Client;
}

describe('runDigest delivery retry', () => {
  it('succeeds and advances the watermark when a transient send failure is retried', async () => {
    getDb().insert(servers).values(serverRow).run();
    addListing();
    const send = vi
      .fn()
      .mockRejectedValueOnce(new Error('transient 503'))
      .mockResolvedValueOnce(undefined);
    const client = fakeClientWithChannelSend(send);

    const result = await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(result.sent).toBe(true);
    expect(result.channelOk).toBe(true);
    expect(send).toHaveBeenCalledTimes(2);
    expect(getServerConfig('500')!.lastDigestAt).toBeGreaterThan(0);
  });

  it('gives up after repeated failures and leaves the watermark unchanged', async () => {
    getDb().insert(servers).values(serverRow).run();
    addListing();
    const send = vi.fn().mockRejectedValue(new Error('persistent failure'));
    const client = fakeClientWithChannelSend(send);

    const result = await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(result.sent).toBe(false);
    expect(result.channelOk).toBe(false);
    expect(getServerConfig('500')!.lastDigestAt).toBe(0);
    expect(send).toHaveBeenCalledTimes(3);
  }, 10_000);
});

describe('runDigest delivery mention safety', () => {
  it('passes allowedMentions with parse: [] to channel send', async () => {
    getDb().insert(servers).values(serverRow).run();
    addListing();
    const sent: { content: string; allowedMentions?: unknown }[] = [];
    const send = vi.fn().mockImplementation((message?: { content: string; allowedMentions?: unknown }) => {
      sent.push(message as any);
      return Promise.resolve();
    });
    const client = fakeClientWithChannelSend(send);

    await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(sent).toHaveLength(1);
    expect(sent[0]).toHaveProperty('content');
    expect(sent[0]).toHaveProperty('allowedMentions');
    expect(sent[0].allowedMentions).toEqual({ parse: [] });
  });
});

describe('runDigest DM delivery', () => {
  it('passes allowedMentions with parse: [] to DM send', async () => {
    getDb().insert(servers).values(serverRowDm).run();
    addListing('501');

    const sent: { content: string; allowedMentions?: unknown }[] = [];
    const fetchUser = vi.fn().mockImplementation(async (userId: string) => {
      if (userId === mockUserWithSpy.id) {
        return mockUserWithSpy;
      }
      return null as any;
    });

    mockUserWithSpy.send.mockImplementation((message: { content: string; allowedMentions?: unknown }) => {
      sent.push(message as any);
      return Promise.resolve();
    });

    const client = {
      users: {
        fetch: fetchUser,
      },
    } as unknown as Client;

    const result = await runDigest(client, getServerConfig('501')!, 'scheduled');

    expect(result.sent).toBe(true);
    expect(result.dmOk).toBe(true);
    expect(result.channelOk).toBe(false);
    expect(sent).toHaveLength(1);
    expect(sent[0]).toHaveProperty('content');
    expect(sent[0]).toHaveProperty('allowedMentions');
    expect(sent[0].allowedMentions).toEqual({ parse: [] });
  });
});
